sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.wrm-cta {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  padding: 22px 24px;
  margin-bottom: 22px;
  display: flex;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
}

.wrm-cta-text { flex: 1; min-width: 240px; }
.wrm-cta-text h2 { margin: 0 0 4px; font-size: 20px; color: var(--ink); }
.wrm-cta-text p  { margin: 0; font-size: 14px; color: var(--ink-2); }

.wrm-cta-btn {
  background: var(--clay);
  color: var(--on-clay);
  font-size: 14px;
  font-weight: 500;
  padding: 11px 24px;
  border-radius: var(--r-pill);
  text-decoration: none;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
  white-space: nowrap;
}

.wrm-cta-btn:hover,
.wrm-cta-btn:focus {
  background: var(--clay-press);
  color: var(--on-clay);
  text-decoration: none;
}

.wrm-cta-btn:focus-visible {
  outline: 2px solid var(--clay);
  outline-offset: 3px;
}

sp_widget.script:
(function() {
  // sys_id of the Workspace Reservation Request catalog item
  data.catItemId = 'fe1e919e93c6c3108c8874dcebba10d0';

  // Build the portal URL for that item. The HTML template
  // reads this as {{data.catUrl}} on the button's href.
  data.catUrl = '?id=sc_cat_item&sys_id=' + data.catItemId;
})();
